namespace hanmo::resident {
namespace {
// 文本输出与中间行共享2MiB预算；超限明确拒绝，不能截断约定或泄漏全世界记录。
struct JournalLines {
    std::vector<StableId> rows;std::size_t bytes=0;bool full=false;
    bool append(StableId value){const auto cost=value.size()+(rows.empty()?0:1);if(cost>2*1024*1024-bytes){full=true;return false;}bytes+=cost;rows.push_back(std::move(value));return true;}
    StableId join()const{StableId text;text.reserve(bytes);for(const auto& row:rows){if(!text.empty())text+='\n';text+=row;}return text;}
};
// 作者名称沿原name_key→title_key→id读取；人物直接目标不冒用运行别名。
StableId authored(const TaskCatalog& catalog,const StableId& table,const StableId& id){auto* value=catalog.presentation_names.find(table+"/"+id);return value?*value:id;}
// 首次获知来源属于本人手记，重复阅读不更新来源或获知时刻。
StableId source_text(const TaskCatalog& catalog,const KnowledgeRecord& known){return "来源：第"+std::to_string(known.discovered_tick/2+1)+"日"+(known.discovered_tick%2==0?"上半日":"下半日")+" · "+(known.source.kind=="actor"?authored(catalog,"actors",known.source.id)+"相告":StableId{"查看当地告示或物件"});}
// 原状态文案只是显示映射，不推断取消重试、逾期或成功资格。
StableId status_name(const StableId& status,const StableId& fallback){static const std::map<StableId,StableId> words={{"unknown","尚未得知"},{"offered","尚未应承"},{"known","已知线索"},{"available","可以问询"},{"active","正在履行"},{"ready","可以回报"},{"success","已履约"},{"late","逾期办妥"},{"expired","期限已过"},{"failed","未能办妥"},{"cancelled","已取消并清算"},{"settling","尚待清算"}};auto found=words.find(status);return found==words.end()?fallback:found->second;}
// 只给手记自己的有限错误，不附带被拒绝的私密事实或另一人物账本。
Outcome<BoundaryValue> rejected(const StableId& code){return {false,{},common_failure(code,"journal_text").error};}
}
static Outcome<BoundaryValue> task_journal_with_sources(const CommonStore& common,const TaskState& tasks,const TaskCatalog& catalog,const CommonCatalog& shared,const InteractionState& interaction,const SocialState& social,const GrowthState& growth,const GovernanceTaskState* governance,const EnvoyTaskState* envoy=nullptr,const DiplomaticMissionRead* missions=nullptr,const DiplomacyPresentationRead* presentations=nullptr,const DiplomaticEnvoyReportRead* reports=nullptr){
    const auto& id=common.state().metadata.player_actor_id;const auto* actor=common.actor(id);if(!actor)return rejected("UnknownActor");const auto* bag=common.inventory(actor->inventory_id);if(!bag)return rejected("UnknownInventory");JournalLines lines;lines.append("行旅手记");lines.append("第"+std::to_string(common.tick()/2+1)+"日"+(common.tick()%2==0?"上半日":"下半日"));lines.append("");std::set<StableId> accepted;Integer finished=0;
    for(const auto& row:tasks.tasks.rows()){const auto& task=row.second;if(task.assignee!=id)continue;accepted.insert(task.offer_id);if(is_state_need_task(tasks,task.id)){const StateNeedTaskContract*contract=nullptr;for(const auto&entry:tasks.state_need_tasks->contracts.rows())if(entry.second.task_id==task.id){if(contract)return rejected("DuplicateStateTaskContract");contract=&entry.second;}const auto*offer=contract?tasks.state_need_tasks->offers.find(contract->offer_id):nullptr;if(!contract||!offer)return rejected("StateTaskSourceMissing");lines.append(offer->goal_summary+" · "+status_name(task.status,"请向原经办人核实"));if(contract->report_required&&!contract->report_receipt)lines.append("尚须按约向收件人实际返报。");if(contract->phase==StateTaskContractPhase::settling)lines.append("执行责任已经停止或达标，原费用与返报仍在清算。");if(contract->phase==StateTaskContractPhase::closed&&task.status=="success")++finished;lines.append("");if(lines.full)return rejected("ResidentFrameLimit");continue;}if(tasks.shop_orders&&tasks.shop_orders->by_task.count(task.id)){auto lines_for_order=task_shop_order_journal_lines(common,tasks,*tasks.shop_orders,catalog,id,task.id);if(!lines_for_order.ok)return {false,{},lines_for_order.error};for(const auto& line:lines_for_order.value)lines.append(line);if(task.status=="success")++finished;lines.append("");if(lines.full)return rejected("ResidentFrameLimit");continue;}if(governance&&governance->governance_contracts.find(task.id)){auto progress=query_governance_task_progress(common,tasks,*governance,task.id);if(!progress.ok)return {false,{},progress.error};for(const auto& line:governance_task_progress_lines(progress.value))lines.append(line);if(progress.value.status=="success")++finished;lines.append("");if(lines.full)return rejected("ResidentFrameLimit");continue;}if(envoy&&envoy->envoy_contracts.find(task.id)){if(!missions||!presentations)return rejected("MissingEnvoyTaskSources");auto progress=query_envoy_task_progress(common,tasks,*envoy,*missions,*presentations,task.id,reports);if(!progress.ok)return {false,{},progress.error};for(const auto& line:envoy_task_progress_lines(progress.value))lines.append(line);if(progress.value.status=="success")++finished;lines.append("");if(lines.full)return rejected("ResidentFrameLimit");continue;}const auto* offer=resolve_task_definition(tasks,catalog,task);if(!offer)return rejected("UnknownOffer");lines.append(offer->display_name+" · "+(task_can_retry(common,tasks,task)?StableId{"受领中断，尚未应承"}:status_name(task.status,"请向经办人问明")));for(const auto& person:interaction.knowledge)if(person.actor_id==id)for(const auto& known:person.offers)if(known.offer_id==task.offer_id)lines.append(source_text(catalog,known));if(offer->template_id=="procurement")lines.append("约定："+authored(catalog,"items",offer->goal.item_id)+" × "+std::to_string(offer->goal.quantity));else if(offer->template_id=="message")lines.append("亲手交给："+authored(catalog,"actors",offer->goal.receiver_actor));else if(offer->template_id=="escort"){lines.append("护送："+authored(catalog,"actors",offer->goal.actor_id)+" → "+authored(catalog,"places",offer->goal.destination_place_id));if(task.escort&&!task.escort->failure.empty())lines.append("护卫未能办妥，请当面报告损失；不能领取成功酬劳。");}auto* role=shared.roles.find(offer->report_role);if(!role)return rejected("UnknownRole");lines.append("回报："+authored(catalog,"places",role->place_id)+" · "+authored(catalog,"roles",offer->report_role));if(task.status=="active"||task.status=="ready"||(task.contract_id&&task.status=="settling")){if(common.tick()>task.deadline_tick)lines.append("约定期限已过 "+std::to_string(common.tick()-task.deadline_tick)+" 个半日；请向合法经办人核对补交或清算，不能按时领奖。");else lines.append("还余 "+std::to_string(task.deadline_tick-common.tick())+" 个半日；以办完交付时刻为准。");auto* budget=common.wallet(task.budget_wallet_id);if(task.contract_id){auto* contract=tasks.contracts.find(*task.contract_id);if(!contract)return rejected("InvalidTaskContract");auto available=common.spendable(task.budget_wallet_id);if(!available.ok)return rejected(available.error.original.code);lines.append("可用采购经费："+std::to_string(available.value)+" 钱；托管酬劳："+std::to_string(contract->frozen_terms.reward_total-contract->paid_reward-contract->refunded_reward)+" 钱");lines.append("实际交付："+std::to_string(contract->delivered_quantity)+" / "+std::to_string(contract->frozen_terms.agreed_quantity)+"；已付酬劳："+std::to_string(contract->paid_reward)+" 钱");if(contract->status==ContractStatus::settling&&!contract->restitution_refs.empty())lines.append("受托货物仍须实际送回或依合法结果清算。");}else if(budget&&offer->budget>0)lines.append("受托经费余额："+std::to_string(budget->balance)+" 钱");}if(task.status=="success")++finished;lines.append("");if(lines.full)return rejected("ResidentFrameLimit");}
    for(const auto& person:interaction.knowledge)if(person.actor_id==id){for(const auto& known:person.offers){if(accepted.count(known.offer_id))continue;auto* offer=resolve_known_offer_definition(tasks,catalog,known.offer_id);if(!offer)return rejected("UnknownOffer");lines.append(offer->display_name+" · "+status_name(task_condition_status(common,tasks,interaction,id,known.offer_id),"已知线索，尚未应承"));lines.append(source_text(catalog,known));if(lines.full)return rejected("ResidentFrameLimit");}break;}
    lines.append("\n随身行囊");if(bag->lots.empty())lines.append("暂未携带货物。");for(const auto& lot:bag->lots){lines.append(authored(catalog,"items",lot.item_id)+" × "+std::to_string(lot.quantity)+" · "+(lot.owner.kind==Owner::Kind::task?"受托保管":"私有"));if(lines.full)return rejected("ResidentFrameLimit");}if(finished>0)lines.append("\n这一程已经兑现了 "+std::to_string(finished)+" 份承诺。你仍可继续访友、行商，或在客舍歇脚。");
    // 原近事只按本人记忆ID排序；社交原始事件优先，未知事实和未结束训练不变成新见闻。
    CommonPresentation presentation(common.state(),shared);auto person_name=[&](const StableId& person,const StableId& fallback){auto* actor=common.state().actors.find(person);if(!actor||!shared.actor_names.find(actor->prototype_id.value_or(person)))return fallback;auto name=presentation.display_name(person);return name.ok?name.value:fallback;};const auto* memories=social.memories.find(id);bool heading=false;if(memories){auto ids=memories->order();std::sort(ids.begin(),ids.end());for(const auto& fact_id:ids){StableId words;if(auto* event=social.events.find(fact_id)){auto who=person_name(event->actor_id,event->actor_id),target=person_name(event->target_actor_id,event->target_actor_id);if(event->kind=="aid")words=who+"拿出"+authored(catalog,"items",event->item_id)+"，接济了"+target+"。";else if(event->kind=="theft")words=who+"取走了"+target+"的"+authored(catalog,"items",event->item_id)+"，引发争执。";else if(event->kind=="refusal")words=who+"没有答应"+target+"的求助。";}else if(const auto* header=common.state().facts.find(fact_id)){if(header->kind=="personal_battle")words="听闻一场比武交锋已有结果。";else if(header->kind=="training"){auto* payload=growth.facts.find(fact_id);auto* training=payload?std::get_if<TrainingFact>(payload):nullptr;if(training&&training->phase=="completed")words=person_name(training->training.student_id,"此人")+"完成了"+authored(catalog,"personal_skills",training->training.skill_id)+"修习。";}}if(words.empty())continue;auto& memory=*memories->find(fact_id);auto source=memory.source_actor_id==id?StableId("亲历"):person_name(memory.source_actor_id,memory.source_actor_id)+"相告";if(!heading){lines.append("\n近事与见闻");heading=true;}lines.append(words+"（第"+std::to_string(memory.learned_tick/2+1)+"日 · "+source+"）");if(lines.full)return rejected("ResidentFrameLimit");}}
    if(lines.full)return rejected("ResidentFrameLimit");return {true,boundary::obj({{"ok",BoundaryValue{true}},{"text",BoundaryValue{lines.join()}}}),{}};
}
// 旧入口没有治理来源，不能凭未知offer名称编造治理进度。
Outcome<BoundaryValue> query_task_journal(const CommonStore& common,const TaskState& tasks,const TaskCatalog& catalog,const CommonCatalog& shared,const InteractionState& interaction,const SocialState& social,const GrowthState& growth){return task_journal_with_sources(common,tasks,catalog,shared,interaction,social,growth,nullptr);}
// 显式登记门只引入本人原治理投影，不建立任务副本或扩张他人的知情范围。
Outcome<BoundaryValue> query_task_journal_with_governance(const CommonStore& common,const TaskState& tasks,const TaskCatalog& catalog,const CommonCatalog& shared,const InteractionState& interaction,const SocialState& social,const GrowthState& growth,const GovernanceTaskState& governance,bool registered){
    if(!registered)return rejected("GovernanceTaskProfileRequired");
    if(governance.version!=1)return rejected("UnsupportedGovernanceTaskVersion");
    return task_journal_with_sources(common,tasks,catalog,shared,interaction,social,growth,&governance);
}
// 原手记只向本人输出已受责任，未知/未登记使者不能被伪装为普通Offer或静默丢掉。
Outcome<BoundaryValue> query_task_journal_with_responsibilities(const CommonStore& common,const TaskState& tasks,const TaskCatalog& catalog,const CommonCatalog& shared,const InteractionState& interaction,const SocialState& social,const GrowthState& growth,const GovernanceTaskState& governance,bool governance_registered,const EnvoyTaskState& envoy,bool envoy_registered,const DiplomaticMissionRead& missions,const DiplomacyPresentationRead& presentations,const DiplomaticEnvoyReportRead* reports){
    if(!governance_registered&&!governance.governance_contracts.rows().empty())return rejected("GovernanceTaskProfileRequired");
    if(!envoy_registered&&!envoy.envoy_contracts.rows().empty())return rejected("EnvoyTaskProfileRequired");
    if(governance.version!=1||(envoy.version!=1&&envoy.version!=2))return rejected("UnsupportedTaskResponsibilityVersion");
    for(const auto& row:envoy.envoy_contracts.rows())if(governance.governance_contracts.find(row.first))return rejected("DuplicateTaskResponsibility");
    return task_journal_with_sources(common,tasks,catalog,shared,interaction,social,growth,governance_registered?&governance:nullptr,envoy_registered?&envoy:nullptr,&missions,&presentations,reports);
}
} // 输出只有一个有界文本字段，不包含原知识索引、他人钱包、隐藏事实或传播算法。
